import pyomo.environ as pyo

DATA = {
    "channels": ["X", "Y"],
    "total_budget_max": 5000,          # combined budget cannot exceed 5000
    "twice_x_minus_y_min": 1000,       # 2*X - Y >= 1000
    "x_minus_thrice_y_max": 2000,      # X - 3*Y <= 2000
    "coef_twice_x": 2,
    "coef_y": 1,
    "coef_thrice_y": 3,
    "cost_per_unit": {"X": 1000, "Y": 1500},
    "budget_upper_bound": 5000,
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.CHANNELS = pyo.Set(initialize=d["channels"])

    model.budget = pyo.Var(
        model.CHANNELS,
        domain=pyo.NonNegativeIntegers,
        bounds=(0, d["budget_upper_bound"]),
    )

    def obj_rule(m):
        return sum(m.budget[c] for c in m.CHANNELS)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def total_budget_rule(m):
        return sum(m.budget[c] for c in m.CHANNELS) <= d["total_budget_max"]

    model.total_budget_limit = pyo.Constraint(rule=total_budget_rule)

    def twice_x_minus_y_rule(m):
        return (
            d["coef_twice_x"] * m.budget["X"] - d["coef_y"] * m.budget["Y"]
            >= d["twice_x_minus_y_min"]
        )

    model.twice_x_minus_y = pyo.Constraint(rule=twice_x_minus_y_rule)

    def x_minus_thrice_y_rule(m):
        return (
            m.budget["X"] - d["coef_thrice_y"] * m.budget["Y"]
            <= d["x_minus_thrice_y_max"]
        )

    model.x_minus_thrice_y = pyo.Constraint(rule=x_minus_thrice_y_rule)

    return model


